import React from 'react';

import { SingleValue } from '../../single-value/SingleValue.js';
import { buildConfig } from '../functions/build-config.js';
import { getConfigFromAccessors } from '../functions/get-config-from-accessors.js';
import { getDataFromAccessors } from '../functions/get-data-from-accessors.js';
import {
  SingleValueGridAccessorsConfig,
  PartialSingleValueGridConfig,
} from '../types/single-value-grid.js';

export const SingleValueRenderer = ({
  record,
  propsConfig,
  accessors,
}: {
  record: string | number | Record<string, unknown>;
  propsConfig: PartialSingleValueGridConfig;
  accessors: SingleValueGridAccessorsConfig;
}) => {
  if (typeof record === 'string' || typeof record === 'number') {
    // in case it is a simple array of strings or numbers, it will just use the props configuration or the defaults
    const config = buildConfig(propsConfig);

    return (
      <SingleValue
        data={record}
        color={config.color}
        formatter={config.value?.formatter}
        unit={config.value?.unit}
        thresholds={config.thresholds}
        alignment={config.alignment}
      >
        {config.trend && <SingleValue.Trend {...config.trend} />}
      </SingleValue>
    );
  }

  const { label, prefixIcon, value, trendData, sparklineData } =
    getDataFromAccessors(record, accessors);

  // in case it is an array of records, it will override the config with the accessors configuration
  const accessorsConfig = getConfigFromAccessors(record, accessors);

  const config = buildConfig(propsConfig, accessorsConfig);

  return (
    <SingleValue
      data={value!}
      label={label}
      prefixIcon={prefixIcon}
      color={config.color}
      formatter={config.value?.formatter}
      unit={config.value?.unit}
      thresholds={config.thresholds}
      alignment={config.alignment}
    >
      {config.sparkline && (
        <SingleValue.Sparkline data={sparklineData!} {...config.sparkline} />
      )}
      {config.trend && (
        <SingleValue.Trend
          value={trendData?.value}
          label={trendData?.label}
          direction={trendData?.direction}
          {...config.trend}
        />
      )}
    </SingleValue>
  );
};
